const { Composer } = require("telegraf");
const FormData = require("form-data");
const FileType = require("file-type");
const { ImageUploadService } = require("node-upload-images");

const fetch = (...args) =>
  import("node-fetch").then(({ default: fetch }) => fetch(...args));

const composer = new Composer();
let enabled = true;


composer.command(["tourl", "upload"], async (ctx) => {
  if (!enabled) return;

  let statusMessage;

  try {
    const msg = ctx.message.reply_to_message || ctx.message;

    let fileId;
    if (msg.photo) fileId = msg.photo.at(-1).file_id;
    else if (msg.document) fileId = msg.document.file_id;
    else if (msg.video) fileId = msg.video.file_id;
    else if (msg.audio) fileId = msg.audio.file_id;
    else if (msg.sticker) fileId = msg.sticker.file_id;
    else return ctx.reply("Reply / kirim media dulu.");

    statusMessage = await ctx.reply("Mengambil file dari Telegram...");

    const fileLink = await ctx.telegram.getFileLink(fileId);
    const res = await fetch(fileLink.href);
    if (!res.ok) throw new Error("Gagal download file Telegram");

    const buffer = Buffer.from(await res.arrayBuffer());
    const fileType = await FileType.fileTypeFromBuffer(buffer);
    const isImage = fileType?.mime?.startsWith("image/");

    const result = {};

    await ctx.telegram.editMessageText(
      ctx.chat.id,
      statusMessage.message_id,
      null,
      "Upload Cloudku..."
    );
    result.cloudku = await cloudkuUpload(buffer).catch(() => null);

    await ctx.telegram.editMessageText(
      ctx.chat.id,
      statusMessage.message_id,
      null,
      "Upload Catbox..."
    );
    result.catbox = await catboxUpload(buffer).catch(() => null);

    if (isImage) {
      await ctx.telegram.editMessageText(
        ctx.chat.id,
        statusMessage.message_id,
        null,
        "Upload Pixhost..."
      );
      result.pixhost = await pixhostUpload(buffer).catch(() => null);
    }

    if (!result.cloudku && !result.catbox && !result.pixhost) {
      return ctx.telegram.editMessageText(
